// PRO: physically based texture sets (pro/tex, generated by tools/pbr_textures.py) on the shared material library.
// UVs of the building are in metres, so repeat = 1 / tile size gives true scale.
import * as THREE from 'three';
import { materials, type MatName } from '../block/materials';
import { furnitureMaterials, type FMat } from '../block/furniture';

type SetName = 'plaster' | 'stucco' | 'brick' | 'parquet' | 'porcelain' | 'terrazzo' | 'walltile' | 'outdoor' | 'concrete'
  | 'polished' | 'gravel' | 'veneer' | 'fabric' | 'leather' | 'brushed' | 'panel';
const TILE: Record<SetName, number> = {
  plaster: 1.5, stucco: 1.0, brick: 1.04, parquet: 1.2, porcelain: 1.2, terrazzo: 1.2, walltile: 1.2, outdoor: 1.2,
  concrete: 2.0, polished: 2.0, gravel: 2.0, veneer: 1.0, fabric: 0.25, leather: 0.4, brushed: 0.6, panel: 1.0,
};
/** rm: multiplier on the map's roughness; metal: constant metalness (the maps only carry metal for brushed steel) */
type Spec = { set: SetName; white?: boolean; n?: number; rm?: number; metal?: number; ao?: number; scale?: number; env?: number };

const BUILDING: Partial<Record<MatName, Spec>> = {
  facade: { set: 'stucco', n: 0.8 }, facade_mint: { set: 'stucco', n: 0.8 }, facade_white: { set: 'stucco', n: 0.8 },
  brick: { set: 'brick', white: true, n: 1.1 },
  paint: { set: 'plaster', n: 0.2 }, paint_public: { set: 'plaster', n: 0.25 }, jamb: { set: 'plaster', n: 0.2 }, ceiling: { set: 'plaster', n: 0.1 },
  tile_wall: { set: 'walltile', white: true }, floor_wood: { set: 'parquet', white: true, env: 1.1 }, floor_tile: { set: 'porcelain', white: true, env: 1.2 },
  floor_stone: { set: 'terrazzo', white: true }, floor_deck: { set: 'outdoor', white: true }, floor_shop: { set: 'polished', white: true },
  floor_base: { set: 'concrete', white: true }, slab_edge: { set: 'stucco', n: 0.6 }, spandrel: { set: 'panel' }, canopy: { set: 'panel', metal: 0.4 },
  frame: { set: 'panel', metal: 0.5, rm: 1.15 }, frame_light: { set: 'panel', metal: 0.5 }, rail: { set: 'panel', metal: 0.6 },
  steel: { set: 'brushed', metal: 1 }, roof: { set: 'gravel', white: true }, pilaster: { set: 'stucco', n: 0.9 }, sill: { set: 'polished', n: 0.5 },
  door_wood: { set: 'veneer' }, door_entry: { set: 'brushed', metal: 0.9 }, stair: { set: 'terrazzo', white: true },
};
const FURN: Partial<Record<FMat, Spec>> = {
  linen: { set: 'fabric', n: 0.6 }, duvet: { set: 'fabric', n: 0.8 }, head: { set: 'fabric' }, fabric: { set: 'fabric' }, rug: { set: 'fabric', n: 1.4, scale: 0.6 },
  woodL: { set: 'veneer' }, woodD: { set: 'veneer' }, leather: { set: 'leather' },
  cabinet: { set: 'panel', rm: 0.8 }, cabinetD: { set: 'panel', rm: 0.9 }, stone: { set: 'porcelain', scale: 0.5, rm: 1.2 },
  steel: { set: 'brushed', metal: 1 },
};

const cache = new Map<string, THREE.Texture>();
let maxAniso = 8;
function tex(name: string, srgb: boolean, repeat: number) {
  const key = `${name}:${repeat}`;
  let t = cache.get(key);
  if (!t) {
    t = new THREE.TextureLoader().load(`pro/tex/${name}.jpg`, () => onLoaded());
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(repeat, repeat);
    t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
    t.anisotropy = maxAniso;
    cache.set(key, t);
  }
  return t;
}
let pending = 0, onLoaded = () => {};

function apply(m: THREE.Material, s: Spec) {
  if (!(m instanceof THREE.MeshStandardMaterial)) return;
  const rep = 1 / (TILE[s.set] * (s.scale ?? 1));
  m.map = tex(`${s.set}_a`, true, rep);
  m.normalMap = tex(`${s.set}_n`, false, rep);
  m.normalScale.set(s.n ?? 1, s.n ?? 1);
  const orm = tex(`${s.set}_orm`, false, rep);
  m.roughnessMap = orm; m.aoMap = orm;
  m.aoMapIntensity = s.ao ?? 0.8;
  m.roughness = s.rm ?? 1;                                   // the map holds the actual roughness
  if (s.set === 'brushed') { m.metalnessMap = orm; m.metalness = 1; } else { m.metalnessMap = null; m.metalness = s.metal ?? 0; }
  if (s.white) m.color.set('#ffffff');
  if (s.env) m.envMapIntensity = s.env;
  m.needsUpdate = true;
  pending++;
}

/** Puts the PBR sets on the building and furniture materials; onReady fires when the textures have arrived. */
export function applyProMaterials(renderer: THREE.WebGLRenderer, onReady: () => void) {
  maxAniso = Math.min(8, renderer.capabilities.getMaxAnisotropy());
  let left = 0;
  onLoaded = () => { if (--left <= 0) onReady(); };
  const lib = materials();
  for (const [k, s] of Object.entries(BUILDING) as [MatName, Spec][]) apply(lib[k], s);
  const f = furnitureMaterials();
  for (const [k, s] of Object.entries(FURN) as [FMat, Spec][]) apply(f[k], s);
  // glass: clearer and more reflective than in the light build, with a slight green tint of float glass
  const g = lib.glass as THREE.MeshPhysicalMaterial;
  g.color.set('#35627f'); g.opacity = 0.8; g.roughness = 0.04; g.metalness = 0.2; g.envMapIntensity = 2.6; g.clearcoat = 1;
  const mirror = f.mirror as THREE.MeshStandardMaterial; mirror.roughness = 0.02; mirror.metalness = 1;
  const porc = f.porcelain as THREE.MeshStandardMaterial; porc.roughness = 0.08;
  left = cache.size;
}

/** Furniture is modelled from unit boxes: give it metric, box-projected UVs so textures keep their real size. */
export function metricUVs(root: THREE.Object3D) {
  root.traverse((o) => {
    const mesh = o as THREE.Mesh;
    if (!mesh.isMesh || mesh.userData.metricUV) return;
    const g = mesh.geometry as THREE.BufferGeometry;
    const p = g.getAttribute('position'), n = g.getAttribute('normal');
    if (!p || !n) return;
    const uv = new Float32Array(p.count * 2);
    for (let i = 0; i < p.count; i++) {
      const ax = Math.abs(n.getX(i)), ay = Math.abs(n.getY(i)), az = Math.abs(n.getZ(i));
      const x = p.getX(i), y = p.getY(i), z = p.getZ(i);
      if (ay >= ax && ay >= az) { uv[i * 2] = x; uv[i * 2 + 1] = z; }
      else if (ax >= az) { uv[i * 2] = z; uv[i * 2 + 1] = y; }
      else { uv[i * 2] = x; uv[i * 2 + 1] = y; }
    }
    g.setAttribute('uv', new THREE.BufferAttribute(uv, 2));
    mesh.userData.metricUV = true;
  });
}
